(() => {
 const images={"AI-blomsten-plakat.png":"","AI-blomsten-plakat-uden-eksempler.png":""};
 document.querySelectorAll('#page-plakat a[download]').forEach(link=>link.addEventListener('click',event=>{
  const filename=link.getAttribute('download'),encoded=images[filename];
  if(!encoded)return;
  event.preventDefault();
  const status=document.getElementById('poster-print-status');
  try{
   const binary=atob(encoded),bytes=new Uint8Array(binary.length);
   for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);
   const url=URL.createObjectURL(new Blob([bytes],{type:'image/png'}));
   const download=document.createElement('a');download.href=url;download.download=filename;
   document.body.append(download);download.click();download.remove();
   setTimeout(()=>URL.revokeObjectURL(url),30000);
   if(status)status.textContent='Download er startet.';
  }catch{if(status)status.textContent='Download kunne ikke startes. Prøv igen.';}
 }));
})();
